/**
 * @method
 * @name scwin.getCookieComCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getCookieComCode = async function () {
    /* sdd-asis-lifecycle:begin getCookieComCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const cookiesStr = scwin.GetCookie('krxComp');
    let totalArray;
    let newVal = "";
    if (cookiesStr != null) {
        totalArray = cookiesStr.split("/");
    }
    const j = 0;
    const sCookieVal = "";
    for (i = 0; j < 11 && i < totalArray.length - 1; i++) {
        const sCookieTemp = totalArray[i].split(",");
        if (i == 0) {
            newVal = newVal + "'" + sCookieTemp[1] + "'";
        } else {
            newVal = newVal + ",'" + sCookieTemp[1] + "'";
        }
    }
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "");
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("allRepIsuSrtCd", newVal);
    await scwin.fncSearch();
    /* sdd-asis-lifecycle:end */
};


